SELECT 
    CASE WHEN home_player_6 IS NOT NULL THEN (
        SELECT pa.jumping FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_api_id = home_player_6
    ) ELSE 0 END AS player_6_jumping,
    CASE WHEN away_player_23 IS NOT NULL THEN (
        SELECT pa.jumping FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_api_id = away_player_23
    ) ELSE 0 END AS player_23_jumping,
    CASE WHEN home_player_6 IS NOT NULL AND away_player_23 IS NOT NULL THEN (
        SELECT pa.jumping FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_api_id = home_player_6
    ) - (
        SELECT pa.jumping FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_api_id = away_player_23
    ) ELSE NULL END AS difference;

